-- Give each seeded employer their primary company so fixture sign-ins land
-- on the dashboard, not onboarding (Week 3).
update public.profiles p
set company_id = c.id
from public.companies c
join auth.users u on u.id = c.owner_id
where p.id = c.owner_id
  and c.slug = case u.email
    when 'employer-a@example.test' then 'northstar-labs'
    when 'employer-b@example.test' then 'cobalt-research'
  end;

