insert into public.jobs (
  company_id, category_id, package_id, title, slug, description_md,
  employment_type, location, is_remote, remote_region, salary_min, salary_max,
  currency, salary_period, apply_mode, apply_url, apply_email, status,
  is_featured, featured_until, published_at, expires_at
)
select c.id, cat.id, p.id, r.title, r.slug, r.description_md,
  r.employment_type::public.employment_type, r.location, r.is_remote, r.remote_region,
  r.salary_min, r.salary_max, r.currency, r.salary_period, r.apply_mode::public.apply_mode,
  r.apply_url, r.apply_email, r.status::public.job_status, r.is_featured,
  r.featured_until::timestamptz, r.published_at::timestamptz, r.expires_at::timestamptz
from job_rows r
join public.companies c on c.slug = r.company_slug
join public.categories cat on cat.slug = r.category_slug
left join public.packages p on p.ls_variant_id = r.package_variant
on conflict (slug) do update set
  company_id = excluded.company_id,
  category_id = excluded.category_id,
  package_id = excluded.package_id,
  title = excluded.title,
  description_md = excluded.description_md,
  employment_type = excluded.employment_type,
  location = excluded.location,
  is_remote = excluded.is_remote,
  remote_region = excluded.remote_region,
  salary_min = excluded.salary_min,
  salary_max = excluded.salary_max,
  currency = excluded.currency,
  salary_period = excluded.salary_period,
  apply_mode = excluded.apply_mode,
  apply_url = excluded.apply_url,
  apply_email = excluded.apply_email,
  status = excluded.status,
  is_featured = excluded.is_featured,
  featured_until = excluded.featured_until,
  published_at = excluded.published_at,
  expires_at = excluded.expires_at;

-- Keep the fixture durable as the calendar advances. The original values above
-- preserve realistic ordering; this pass makes every reset produce the same
-- live/workflow distribution relative to the reset time.
with ranked_live as (
  select id, row_number() over (order by published_at, slug) as position
  from public.jobs
  where status = 'published'::public.job_status
)
update public.jobs j
set published_at = now() - make_interval(days => ranked_live.position::integer),
    expires_at = now() + interval '30 days',
    featured_until = case when j.is_featured then now() + interval '14 days' else null end
from ranked_live
where j.id = ranked_live.id;

update public.jobs
set published_at = now() - interval '45 days',
    expires_at = now() - interval '1 day',
    featured_until = null
where status = 'expired'::public.job_status;

update public.jobs
set published_at = null,
    expires_at = null,
    featured_until = null
where status in ('draft'::public.job_status, 'pending_review'::public.job_status, 'rejected'::public.job_status);

update public.jobs
set description_md = E'## The role\n\nOwn the systems that help thousands of teams ship dependable software.\n\n- Work across TypeScript and Postgres\n- Improve thoughtful developer tooling\n- Share decisions clearly with the team\n\n```ts\nexport const dependable = true\n```'
where slug = 'senior-typescript-engineer';

