  ('backend-engineer-data-apis', 'python'), ('backend-engineer-data-apis', 'postgres'),
  ('product-manager-care-navigation', 'healthcare'), ('senior-product-designer-juniper', 'figma'),
  ('analytics-engineer-juniper', 'analytics'), ('machine-learning-engineer-mosaic', 'machine-learning'),
  ('open-source-maintainer', 'open-source'), ('senior-rust-engineer', 'rust'),
